import{_ as t,c as n,o as s,ag as i}from"./chunks/framework.Bzez9NG9.js";const u=JSON.parse('{"title":"SPACE Python SDK","description":"Use the SPACE Python SDK from scripts and notebooks to securely access SPACE-managed resources such as secrets and connection configuration.","frontmatter":{"title":"SPACE Python SDK","description":"Use the SPACE Python SDK from scripts and notebooks to securely access SPACE-managed resources such as secrets and connection configuration.","keywords":["SPACE Python SDK","Python SDK","SPACE_TOKEN","get_secret","get_connection_config","connections.names","secrets","connections"],"outline":"deep"},"headers":[],"relativePath":"doc/python/sdk.md","filePath":"doc/python/sdk.md"}'),a={name:"doc/python/sdk.md"};function o(c,e,r,h,l,p){return s(),n("div",null,e[0]||(e[0]=[i(`<h1 id="space-python-sdk" tabindex="-1">SPACE Python SDK <a class="header-anchor" href="#space-python-sdk" aria-label="Permalink to &quot;SPACE Python SDK&quot;">​</a></h1><p>The SPACE Python SDK provides a Python interface to supported SPACE capabilities from scripts and Jupyter notebooks.</p><p>It is designed for Python code running inside SPACE, allowing scripts to use centrally managed configuration without hard-coding SPACE API calls, authentication tokens, credentials, or environment-specific connection details.</p><p>A primary use case is secure access to <a href="./secrets-and-connections.html">secrets and connections</a>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Python executions inside SPACE receive a SPACE authentication token through the execution environment.</p><p>The SDK uses this authentication when communicating with the SPACE API, so scripts and notebooks do not need to embed a SPACE token in source code.</p><p>This also allows the same Python code to be reused without maintaining a separate SPACE API credential in the project.</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><p>Use the SDK to retrieve a named secret when Python code needs credentials or another sensitive value managed by SPACE.</p><p>The detailed secret API, returned fields, and examples are documented under <a href="./secrets-and-connections.html">Secrets and connections</a>.</p><p>A typical workflow is:</p><ol><li>An administrator creates the secret in SPACE.</li><li>Python code requests the secret by name.</li><li>The script uses the returned fields at runtime.</li><li>The credentials remain outside the Python source code and Git repository.</li></ol><h2 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h2><p>The SDK can also expose configured SPACE connections to Python.</p><p>Import <code>secrets</code> and <code>connections</code> from the <code>space</code> package:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> space </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> secrets, connections</span></span></code></pre></div><p>Use <code>connections.get()</code> to retrieve a configured SPACE connection:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> connections.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TeamOneTest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(config)</span></span></code></pre></div><p>Use <code>secrets.get()</code> to retrieve a named secret:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">username </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> secrets.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Workday PROD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The returned connection configuration can include the endpoint and authentication information required by a Python client library.</p><p>This makes it possible to reuse centrally configured connections rather than maintaining a second set of connection settings for Python.</p><h2 id="using-the-sdk-with-other-python-libraries" tabindex="-1">Using the SDK with other Python libraries <a class="header-anchor" href="#using-the-sdk-with-other-python-libraries" aria-label="Permalink to &quot;Using the SDK with other Python libraries&quot;">​</a></h2><p>The SDK does not replace libraries used to communicate with external systems. Instead, it can provide the configuration and credentials those libraries need.</p><p>For example, a Python workflow can:</p><ol><li>retrieve a configured IBM Planning Analytics connection from SPACE;</li><li>obtain its connection and authentication settings;</li><li>pass those values to TM1py;</li><li>use TM1py for the Planning Analytics operation.</li></ol><p>See <a href="./tm1py.html">TM1py</a> for Planning Analytics examples.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>Avoid copying retrieved credentials into notebooks, logs, output, or source-controlled files.</p><p>The purpose of the SDK is to allow Python code to use centrally managed values at runtime while keeping sensitive configuration outside the code itself.</p><p>See <a href="./secrets-and-connections.html">Secrets and connections</a> for practical usage patterns.</p>`,32)]))}const k=t(a,[["render",o]]);export{u as __pageData,k as default};
